import { Component, Input } from '@angular/core';
import { TotalStats } from '../../models/health-data.model';

@Component({
  selector: 'app-weekly-progress',
  templateUrl: './weekly-progress.component.html',
  styleUrls: ['./weekly-progress.component.scss']
})
export class WeeklyProgressComponent {
  @Input() totalStats: TotalStats | null = null;

  formatValue(value: number): string {
    return value.toLocaleString();
  }

  roundValue(value: number): number {
    return Math.round(value);
  }
}
<div class="grid grid-cols-2 lg:grid-cols-4 gap-3 sm:gap-4">
  <div class="bg-white/20 backdrop-blur-sm rounded-xl p-3 sm:p-4 text-center shadow-lg border border-white/30">
    <div class="text-lg sm:text-2xl font-bold text-white mb-1">{{ formatValue(totalStats?.totalSteps || 0) }}</div>
    <div class="text-xs sm:text-sm text-white/80">Total Steps</div>
  </div>
  <div class="bg-white/20 backdrop-blur-sm rounded-xl p-3 sm:p-4 text-center shadow-lg border border-white/30">
    <div class="text-lg sm:text-2xl font-bold text-white mb-1">{{ formatValue(totalStats?.totalCalories || 0) }}</div>
    <div class="text-xs sm:text-sm text-white/80">Total Calories</div>
  </div>
  <div class="bg-white/20 backdrop-blur-sm rounded-xl p-3 sm:p-4 text-center shadow-lg border border-white/30">
    <div class="text-lg sm:text-2xl font-bold text-white mb-1">{{ totalStats?.totalUploads || 0 }}</div>
    <div class="text-xs sm:text-sm text-white/80">Total Uploads</div>
  </div>
  <div class="bg-white/20 backdrop-blur-sm rounded-xl p-3 sm:p-4 text-center shadow-lg border border-white/30">
    <div class="text-lg sm:text-2xl font-bold text-white mb-1">{{ formatValue(totalStats?.averageSteps || 0) }}</div>
    <div class="text-xs sm:text-sm text-white/80">Avg Steps</div>
  </div>
</div>
